import{z as d,x as c,o as r,c as A,q as i,j as s,D as E,d as a,s as n,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"特权级","description":"","frontmatter":{"title":"特权级","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/privilege-rings.md","filePath":"cs/privilege-rings.md","lastUpdated":1791413859000}'),B={name:"cs/privilege-rings.md"};function p(C,e,m,S,h,u){const o=c("Mermaid");return r(),A("div",null,[e[2]||(e[2]=i('<h1 id="特权级" tabindex="-1">特权级 <a class="header-anchor" href="#特权级" aria-label="Permalink to &quot;特权级&quot;">​</a></h1><div class="epigraph"><p>用户程序不能随便写 `mtvec` 或关中断；硬件用特权级挡住这些 CSR 与指令，陷入时才升到能处理入口的那一层。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；The RISC-V Instruction Set Manual, Volume II: Privileged Architecture 整理</footer></div><p>上一课<a href="/cs/plic-irq">PLIC 与中断号</a>钉死了保存 PC、跳到 <code>mtvec</code>。本课不重列 <code>mcause</code> 编码，也不从操作系统内核源码另起。缺口是：若用户指令也能写 <code>mtvec</code>、执行 <code>mret</code>、关全局中断，入口机制立刻被架空。必须把执行模式分成<strong>特权级</strong>，CSR 与某些指令只在足够高的级合法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RV32I 用户级子集没有模式。缺口是 RISC-V 的 M/S/U（教学可先 M 与 U）：当前级存在 CSR <code>mstatus</code> 等里。用户执行 <code>csrw mtvec</code> 或 <code>mret</code> 会非法指令异常。<code>ecall</code> 从 U 陷入 M（或 S），硬件升特权并关部分中断，入口代码才可信。返回 <code>mret</code>/<code>sret</code> 降特权、恢复 PC。</p><p>本课只钉「级」与「陷入升、返回降」。页表、用户/内核地址空间是体系结构与 OS 课；这里还没有虚存。组成课主干到此；下一课<a href="/cs/booth-multiplier">Booth 乘法</a>打开算术单元，把单周期图切开重叠留给后面的<a href="/cs/pipeline-five-stage">流水线五级</a>一课。</p><h3 id="特权级不是「环上的操作系统产品名」" tabindex="-1">特权级不是「环上的操作系统产品名」 <a class="header-anchor" href="#特权级不是「环上的操作系统产品名」" aria-label="Permalink to &quot;特权级不是「环上的操作系统产品名」&quot;">​</a></h3><p>x86 的 ring 0–3 是另一套编码；本栏用 RISC-V 的 M/S/U。不要把「Ring 0」当 RISC-V 术语。级也不等于进程：同一 U 级可以有许多进程，那是 OS 用页表造出来的，本课没有。</p><p><span class="marginnote">特权手册定义 M 必现，S 可选。Patterson/Hennessy 用用户/内核对照说明为何异常要换模式。本课不把 SELinux、虚拟化 H 扩展展开。</span></p><p><span class="marginnote">直觉类比：特权级像飞机驾驶舱——乘客（U 级）可以按呼叫铃请求服务（ecall），但驾驶杆与仪表（CSR）只有机组（M 级）能碰；挡在中间的是舱门硬件，不是礼貌。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件维护当前特权。译码时检查指令是否允许：不允许则异常。陷入：保存先前级，当前级 ← 处理该陷阱的级（如 M）。<code>mret</code>：当前级 ← 保存的先前级。中断使能位按级屏蔽，避免入口未保存寄存器时再入。</p>',12)),(r(),s(l,null,{default:E(()=>[n(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22U%EF%BC%9A%E7%94%A8%E6%88%B7%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20ECALL%5B%22ecall%20%2F%20%E6%95%85%E9%9A%9C%20%2F%20%E4%B8%AD%E6%96%AD%22%5D%0A%20%20ECALL%20--%3E%20M%5B%22M%EF%BC%9A%E5%85%A5%E5%8F%A3%E4%B8%8E%20CSR%22%5D%0A%20%20M%20--%3E%20MRET%5B%22mret%20%E9%99%8D%E5%9B%9E%20U%22%5D%0A%20%20MRET%20--%3E%20U%0A%20%20M%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%B5%81%E6%B0%B4%E7%BA%BF%E9%87%8D%E5%8F%A0%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=t("p",null,[a("有了级，存储程序机器才分得出「普通加法」与「改入口向量」。后课内核/用户态是本课在 OS 里的名字；系统调用路径 = "),t("code",null,"ecall"),a(" + 本课升级。设备 MMIO 也可以只在 M 可访问，本课只要求检查存在。")],-1)),e[5]||(e[5]=t("p",null,"同一条特权指令，在两级上运行会走向两种结局——保护正是这道检查：",-1)),(r(),s(l,null,{default:E(()=>[n(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E6%8C%87%E4%BB%A4%20csrw%20mtvec%22%5D%20--%3E%20CHK%7B%22%E8%AF%91%E7%A0%81%E6%97%B6%E6%9F%A5%E5%BD%93%E5%89%8D%E7%89%B9%E6%9D%83%E7%BA%A7%22%7D%0A%20%20CHK%20--%3E%7C%22%E8%BF%90%E8%A1%8C%E4%BA%8E%20M%20%E7%BA%A7%22%7C%20OK%5B%22%E5%90%88%E6%B3%95%20%E5%86%99%E5%85%A5%E9%99%B7%E9%98%B1%E5%85%A5%E5%8F%A3%E5%90%91%E9%87%8F%22%5D%0A%20%20CHK%20--%3E%7C%22%E8%BF%90%E8%A1%8C%E4%BA%8E%20U%20%E7%BA%A7%22%7C%20BAD%5B%22%E8%A7%A6%E5%8F%91%E9%9D%9E%E6%B3%95%E6%8C%87%E4%BB%A4%E5%BC%82%E5%B8%B8%22%5D%0A%20%20BAD%20--%3E%20TRAP%5B%22%E4%BF%9D%E5%AD%98%20PC%20%E5%8D%87%E5%88%B0%20M%20%E8%B7%B3%20mtvec%22%5D%0A%20%20TRAP%20--%3E%20HAND%5B%22%E5%86%85%E6%A0%B8%E8%A3%81%E5%86%B3%20%E5%B8%B8%E8%A7%81%E7%BB%93%E6%9E%9C%E6%98%AF%E6%9D%80%E6%8E%89%E8%BF%9B%E7%A8%8B%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p><span class="marginnote">为什么重要：如果用户代码能写 mtvec，它就能把陷阱入口指到自己的代码——下一次任何中断或异常都会把 CPU 连同最高特权一起交出来，整个保护体系从入口开始崩塌。</span></p><p>组成课不把流水线冒险算进特权：特权是状态，流水线是执行重叠。两者在「流水线异常」叶子才会交汇。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现分页、不讲 TEE、不把安全栏的沙箱提前。虚拟机监控的两层翻译是更后的附录或 OS/体系交界。数字逻辑与计算机组成课程到此收束：能跑带陷阱的 RISC-V 整数核、分用户与机器模式。</p><p>后课默认：用户代码在 U，陷阱在更高特权处理。再往后：一条指令仍太慢，要用五级流水重叠。</p><p><span class="marginnote">常见误区：把「Ring 0」当通用术语。x86 的 ring 0–3 与 RISC-V 的 M/S/U 是两套编码；RISC-V 只保证 M 必现、S 可选，常见配置就 M 和 U 两级——级数不同，机制同构。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>特权级限制 CSR 与 <code>mret</code> 等指令；陷入升、<code>mret</code> 降。</li><li>用户不能改自己的陷阱入口。</li><li>组成主干停在可编程、可陷阱、分模式的 RISC-V 核；流水线是后面的课程。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；RISC-V Privileged Spec。</li></ul>',8))])}const R=d(B,[["render",p]]);export{g as __pageData,R as default};
